from flask import Flask, request, Response, jsonify
import os
import json
import requests

app = Flask(__name__)

# GLM-5 API Configuration
GLM_API_URL = ""

def get_api_key():
    """Get API key from environment"""
    api_key = os.environ.get('GLM_API_KEY')
    if not api_key:
        raise ValueError("GLM_API_KEY environment variable is not set")
    return api_key

@app.route('/')
def index():
    """Serve the frontend"""
    with open('index.html', 'r', encoding='utf-8') as f:
        return f.read()

@app.route('/api/chat', methods=['POST'])
def chat():
    """Handle chat requests with GLM-5 API"""
    try:
        data = request.json
        messages = data.get('messages', [])
        search_enabled = data.get('searchEnabled', False)

        if not messages:
            return jsonify({'error': 'No messages provided'}), 400

        # Prepare request to GLM-5 API
        api_key = get_api_key()

        # Build the request payload with all features
        payload = {
            "model": "glm-5",
            "messages": messages,
            "stream": True,  # Enable streaming for real-time responses
            "thinking": {
                "type": "enabled",  # Enable thinking mode for GLM-5
                "clear_thinking": True
            },
            "max_tokens": 8192,  # Maximum output tokens
            "temperature": 0.7,
            "top_p": 0.9,
            "do_sample": True
        }

        # Add web search if enabled
        if search_enabled:
            payload["tools"] = [{
                "type": "web_search",
                "web_search": {
                    "enable": True,
                    "search_query": messages[-1].get('content', '') if messages else ''
                }
            }]

        headers = {
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json'
        }

        # Make streaming request to GLM-5 API
        def generate():
            """Stream responses from GLM-5 API"""
            try:
                response = requests.post(
                    GLM_API_URL,
                    headers=headers,
                    json=payload,
                    stream=True,
                    timeout=60
                )

                if response.status_code != 200:
                    error_msg = f"API Error: {response.status_code} - {response.text}"
                    yield f"data: {json.dumps({'error': error_msg})}\n\n"
                    return

                # Stream the response
                for line in response.iter_lines():
                    if line:
                        line_str = line.decode('utf-8')

                        # Handle SSE format
                        if line_str.startswith('data: '):
                            data_content = line_str[6:]  # Remove 'data: ' prefix

                            # Check for end of stream
                            if data_content.strip() == '[DONE]':
                                yield f"data: [DONE]\n\n"
                                break

                            try:
                                # Parse the JSON data
                                chunk_data = json.loads(data_content)

                                # Extract content and reasoning from the response
                                if 'choices' in chunk_data and len(chunk_data['choices']) > 0:
                                    choice = chunk_data['choices'][0]
                                    delta = choice.get('delta', {})

                                    # Build response object
                                    response_obj = {}

                                    # Regular content
                                    if 'content' in delta and delta['content']:
                                        response_obj['content'] = delta['content']

                                    # Thinking/reasoning content (from GLM-5 thinking mode)
                                    if 'reasoning_content' in delta and delta['reasoning_content']:
                                        response_obj['reasoning'] = delta['reasoning_content']

                                    # Web search results
                                    if 'web_search' in chunk_data:
                                        response_obj['web_search'] = chunk_data['web_search']

                                    # Send the chunk to frontend
                                    if response_obj:
                                        yield f"data: {json.dumps(response_obj)}\n\n"

                            except json.JSONDecodeError:
                                # Skip malformed JSON
                                continue

                # Send final done message
                yield f"data: [DONE]\n\n"

            except requests.exceptions.Timeout:
                yield f"data: {json.dumps({'error': 'Request timeout'})}\n\n"
            except requests.exceptions.RequestException as e:
                yield f"data: {json.dumps({'error': f'Request failed: {str(e)}'})}\n\n"
            except Exception as e:
                yield f"data: {json.dumps({'error': f'Unexpected error: {str(e)}'})}\n\n"

        return Response(generate(), mimetype='text/event-stream')

    except ValueError as e:
        return jsonify({'error': str(e)}), 500
    except Exception as e:
        return jsonify({'error': f'Server error: {str(e)}'}), 500

@app.route('/api/health', methods=['GET'])
def health():
    """Health check endpoint"""
    try:
        api_key = get_api_key()
        return jsonify({
            'status': 'ok',
            'api_configured': bool(api_key)
        })
    except:
        return jsonify({
            'status': 'error',
            'api_configured': False
        }), 500

if __name__ == '__main__':
    # Check for API key on startup
    try:
        api_key = get_api_key()
        print(f"✓ GLM API key configured")
    except ValueError:
        print("⚠ Warning: GLM_API_KEY not set. Please configure it in Secrets.")

    # Run the server on 0.0.0.0:5000 for Replit
    app.run(host='0.0.0.0', port=5000, debug=False)

